// Play it with ?stage=secret (or ?stage=7). Everything marked PLACEHOLDER is to be replaced: the 'S' sea is shallow water you can drive through (it will be an ocean that freezes), the barracks is the
// power plant, the gate is the laser fence. The summit and its boss come later.
import terrain from './terrain.txt?raw';
import data from './entities.json';
import summit from './summit.json'; // the summit road in the west: its path, and its trail (tools/secret_to_level.py)
import summit2 from './summit2.json'; // the second ascent in the north: the road that switches back up to the boss's plateau
import minefield from './minefield.json'; // the north shore's mines and warning signs (map pixels)

const NORTH_ROWS = 150; // the map runs 150 rows (187.5 m) further north than the hand-placed data below was drawn for (tools/secret_to_level.py NORTH): its rows and pixels are moved down by that much
const TOP_Z = -270 - NORTH_ROWS * 1.25, wc = (x, z, w = 1) => [(x + 125) / 1.25 - .5, (z - TOP_Z) / 1.25 - .5, w]; // (world metres to map cells, for tracks placed by hand)
// Five medium tanks along the second ascent's long road, parked on its shoulders (alternating sides, near the road's edge, so the jeep can still get by), each facing down the road at the jeep as it climbs;
// off the tight turns (where the road narrows). Placed from the road's own points, turned into the level's pixel units (1.25 m to 8 px).
const roadTanks = [.14, .3, .47, .64, .8].map((f, k) => {
  const pts = summit2.pts; let i = Math.round(f * (pts.length - 1)); while (i < pts.length - 8 && (pts[i][3] ?? 1) < .95) i++;
  const p = pts[i], a = pts[Math.max(0, i - 4)], b = pts[Math.min(pts.length - 1, i + 4)]; let tx = b[0] - a[0], tz = b[1] - a[1]; const l = Math.hypot(tx, tz) || 1; tx /= l; tz /= l;
  const side = k % 2 ? -1 : 1, off = summit2.halfW - 1.8, x = p[0] - tz * side * off, z = p[1] + tx * side * off;   // (off: on the shoulder, 1.8 m in from the road's edge, whatever its width)
  return { type: 'mediumtank', x: x / (1.25 / 8) + data.meta.width / 2, y: z / (1.25 / 8) + data.meta.height, yaw: Math.atan2(tx, tz) };   // (yaw: facing back down the road)
});
const down = p => ({ ...p, y: p.y + NORTH_ROWS * 8 });

